DO $$
DECLARE
    v_timestamp bigint := (extract(epoch from now()) * 1000)::bigint;
    v_new_bank jsonb := '[{"id":"q_past_1","source":"Past Exam","topic":"Formative 1","text":"The primary preventive strategy for community-acquired pneumonia is","options":{"A":"Antibiotic therapy","B":"Good hand hygiene","C":"Adherence to healthy lifestyle behaviors","D":"Immunization with pneumococcal and influenza vaccines."},"correctOption":"D","explanation":"Pneumococcal and influenza vaccination is the key preventive measure highlighted for community-acquired pneumonia."},{"id":"q_past_2","source":"Past Exam","topic":"Formative 1","text":"A 30 years man from Australia returned from a business trip to Indonesia 6d ago presenting with complaints of fever, joint and muscle ache and headache, in particular behind the eye for the past 2 days. What is the most probable diagnosis?","options":{"A":"Malaria","B":"Chicken pox","C":"TB","D":"Lyme''s disease","E":"Dengue"},"correctOption":"E","explanation":"The travel history plus acute fever, myalgia/arthralgia, and retro-orbital headache are the classic clinical pattern of dengue in the source."},{"id":"q_past_3","source":"Past Exam","topic":"Formative 1","text":"Which of the following is not a RNA virus?","options":{"A":"Hepatitis A virus","B":"Hepatitis B virus","C":"Hepatitis C virus","D":"Hepatitis D virus"},"correctOption":"B","explanation":"Hepatitis B virus is a DNA virus, unlike the other listed hepatitis viruses that contain RNA."},{"id":"q_past_4","source":"Past Exam","topic":"Formative 1","text":"The following statements are true regarding leptospirosis, except","options":{"A":"It is zoonosis","B":"Man is the dead end host","C":"Man is an accidental host","D":"Lice act as reservoirs of infection"},"correctOption":"D","explanation":"Leptospirosis is a zoonosis associated with animal reservoirs; lice are not its reservoir in the source."},{"id":"q_past_5","source":"Past Exam","topic":"Formative 1","text":"Worldwide, the most common mode of infection with HIV is?","options":{"A":"Homosexual transmission","B":"Heterosexual transmission","C":"Blood and blood products","D":"Infected mothers to infants"},"correctOption":"B","explanation":"The source identifies heterosexual sexual transmission as the commonest worldwide mode of HIV acquisition."},{"id":"q_past_6","source":"Past Exam","topic":"Formative 1","text":"Release of which of the following results in fever?","options":{"A":"Interleukin (IL) 1","B":"Interleukin (IL) 8","C":"Granulocyte colony-stimulating factor","D":"All of the above"},"correctOption":"A","explanation":"IL-1 is an endogenous pyrogen that contributes to fever through hypothalamic prostaglandin-mediated temperature elevation."},{"id":"q_past_7","source":"Past Exam","topic":"Formative 1","text":"The single most useful clinical sign of severity of pneumonia in a person without underlying lung disease is?","options":{"A":"Respiratory rate >30/minute","B":"Pulse rate >100/minute","C":"Hypothermia","D":"Postural fall of SBP >10 mm Hg"},"correctOption":"A","explanation":"Marked tachypnea is an important clinical marker of pneumonia severity."},{"id":"q_past_8","source":"Past Exam","topic":"Formative 1","text":"Hospital-acquired pneumonia (HAP) is defined as pneumonia occurring how many hours after hospital admission?","options":{"A":"At least 12 hours","B":"At least 24 hours","C":"At least 36 hours","D":"At least 48 hours"},"correctOption":"D","explanation":"Pneumonia developing at least 48 hours after admission is classified as hospital-acquired pneumonia in this source."},{"id":"q_past_9","source":"Past Exam","topic":"Formative 1","text":"Which bacterial pathogen is most common cause of community-acquired pneumonia in adults?","options":{"A":"Staphylococcus aureus","B":"Mycoplasma pneumoniae","C":"Streptococcus pneumoniae","D":"Chlamydophila pneumoniae"},"correctOption":"C","explanation":"S. pneumoniae is the classic common bacterial cause of community-acquired pneumonia in adults."},{"id":"q_past_10","source":"Past Exam","topic":"Formative 1","text":"A 7-year school boy has been diagnosed with meningococcal meningitis. What is the advice for schoolmates and staff?","options":{"A":"Rifampicin for the whole class and family","B":"Rifampicin for the whole school and family","C":"Meningococcal vaccine for the family","D":"Benzylpenicillin","E":"IV cefotaxime"},"correctOption":"A","explanation":"Close contacts of meningococcal disease require chemoprophylaxis; rifampicin is the source-marked choice."},{"id":"q_past_11","source":"Past Exam","topic":"Formative 2","text":"Rifampicin is used in all except","options":{"A":"Legionnaires'' disease","B":"Chemoprophylaxis of meningococcus meningitis","C":"Leprosy","D":"Bartonellosis"},"correctOption":"D","explanation":"The source lists Bartonella infection as the exception among the listed rifampicin uses."},{"id":"q_past_12","source":"Past Exam","topic":"Formative 2","text":"Most reliable clue to poor tissue perfusion in septic shock is","options":{"A":"Hyponatraemia","B":"High level of blood lactate","C":"Hypochloraemia","D":"Low level of HCO3"},"correctOption":"B","explanation":"Elevated lactate reflects impaired tissue perfusion and anaerobic metabolism, making it a useful marker in septic shock."},{"id":"q_past_13","source":"Past Exam","topic":"Formative 2","text":"Microbial flora of GI tract does not contain","options":{"A":"Bacteroides fragilis","B":"Clostridium perfringens","C":"Pseudomonas","D":"Klebsiella ozaenae"},"correctOption":"D","explanation":"The source treats K. ozaenae as not part of the normal gastrointestinal microbial flora in this question."},{"id":"q_past_14","source":"Past Exam","topic":"Formative 2","text":"Which of the following are the features of enteric fever in the first week","options":{"A":"Continued type pyrexia","B":"Pea-soup diarrhoea","C":"Relative tachycardia","D":"Typhoid state"},"correctOption":"A","explanation":"Continuous/continued fever is a characteristic early feature of enteric (typhoid) fever."},{"id":"q_past_15","source":"Past Exam","topic":"Formative 2","text":"Which is true in Widal test?","options":{"A":"Relapse bears relationship with agglutinin titre","B":"Agglutinin against flagellar antigen is most important","C":"Agglutinins begin to appear after 3rd day of infection","D":"Agglutinins reach a peak titre during the fifth or sixth week"},"correctOption":"D","explanation":"The source states that Widal agglutinins reach peak titre during the fifth or sixth week."},{"id":"q_past_16","source":"Past Exam","topic":"Formative 2","text":"Treatment of choice in chronic carrier of enteric fever is","options":{"A":"Cholecystectomy","B":"Quinolones","C":"Ceftriaxone","D":"Furazolidone"},"correctOption":"A","explanation":"Chronic enteric-fever carriage may persist in the gallbladder; the source therefore marks cholecystectomy."},{"id":"q_past_17","source":"Past Exam","topic":"Formative 2","text":"Rat-bite fever is caused by the organism","options":{"A":"Spirillum minus","B":"A gram-positive cocci","C":"Yersinia multocida","D":"Treponema pertenue"},"correctOption":"A","explanation":"Spirillum minus is the organism classically associated with rat-bite fever in the source."},{"id":"q_past_18","source":"Past Exam","topic":"Formative 2","text":"Cyclical periods of pyrexia alternating with apyrexia is found in all except","options":{"A":"Relapsing fever","B":"Leprosy","C":"Hodgkin''s disease","D":"Brucellosis"},"correctOption":"B","explanation":"Leprosy is not classically characterized by cyclical fever alternating with afebrile periods, making it the exception here."},{"id":"q_past_19","source":"Past Exam","topic":"Formative 2","text":"Drug of choice in pneumonic legionellosis is","options":{"A":"Rifampicin","B":"Ceftazidime","C":"Erythromycin","D":"Co-amoxyclav"},"correctOption":"C","explanation":"The source identifies erythromycin as the treatment choice for pneumonic Legionella infection."},{"id":"q_past_20","source":"Past Exam","topic":"Formative 2","text":"Faget''s sign (relative bradycardia) is first described in","options":{"A":"Typhoid fever","B":"Yellow fever","C":"Acute rheumatic fever","D":"Brucellosis"},"correctOption":"B","explanation":"Faget sign (relative bradycardia with fever) is classically associated with yellow fever in this source."},{"id":"q_past_21","source":"Past Exam","topic":"Formative 2","text":"Cat-scratch disease is characterized by all except","options":{"A":"Regional lymphadenopathy","B":"Erythema nodosum","C":"Positive Hanger-Rose intradermal test","D":"Treated by antibiotic and corticosteroid"},"correctOption":"D","explanation":"The source identifies this treatment statement as the exception for cat-scratch disease."},{"id":"q_past_22","source":"Past Exam","topic":"Formative 2","text":"Cerebral malaria is","options":{"A":"Treated by oral quinine sulphate","B":"Often complicated by multi-organ failure","C":"Associated with signs of meningeal irritation","D":"IV dexamethasone reduces mortality rate"},"correctOption":"B","explanation":"Severe cerebral malaria can be complicated by systemic organ dysfunction and multi- organ failure."},{"id":"q_past_23","source":"Past Exam","topic":"Formative 2","text":"Regarding primary amoebic meningoencephalitis, which is false","options":{"A":"Almost invariably fatal","B":"Caused by Naegleria fowleri","C":"Dehydroemetine is drug of choice","D":"Acquired by swimming in fresh warm water"},"correctOption":"C","explanation":"The source marks dehydroemetine as the false statement for primary amoebic meningoencephalitis."},{"id":"q_past_24","source":"Past Exam","topic":"Formative 2","text":"River blindness is due to","options":{"A":"Toxoplasmosis","B":"Trichinosis","C":"Onchocerciasis","D":"Cysticercosis"},"correctOption":"C","explanation":"Onchocerciasis due to Onchocerca volvulus is the cause of river blindness."},{"id":"q_past_25","source":"Past Exam","topic":"Formative 2","text":"Drug of choice in Pneumocystis carinii pneumonia is","options":{"A":"Pentamidine isethionate","B":"Zidovudine","C":"Cefoperazone","D":"Aztreonam"},"correctOption":"A","explanation":"The source marks pentamidine isethionate as the treatment choice for Pneumocystis pneumonia."},{"id":"q_past_26","source":"Past Exam","topic":"Formative 2","text":"In hepatic amoebiasis","options":{"A":"Left lobe is commonly affected","B":"Liver function tests (LFT) are of diagnostic value","C":"Jaundice is uncommon","D":"Serological tests are not helpful in diagnosis"},"correctOption":"C","explanation":"In hepatic amoebiasis, jaundice is not a usual feature and is therefore uncommon."},{"id":"q_past_27","source":"Past Exam","topic":"Formative 2","text":"Tuberculous focus in brain is known as","options":{"A":"Rich''s focus","B":"Wigard''s focus","C":"Ashman''s focus","D":"Simmon''s focus"},"correctOption":"A","explanation":"A Rich focus is a small tuberculous focus in the brain that can later contribute to tuberculous meningitis."},{"id":"q_past_28","source":"Past Exam","topic":"Formative 2","text":"Malta fever is caused by","options":{"A":"Pasteurella tularensis","B":"Haemophilus influenzae","C":"Brucella abortus","D":"Pseudomonas mallei"},"correctOption":"C","explanation":"Brucella abortus is a major cause of brucellosis and is associated with the classic occupational/animal exposure setting."},{"id":"q_past_29","source":"Past Exam","topic":"Formative 2","text":"Which is false regarding brucellosis","options":{"A":"Acquired through contact or ingestion of raw goat''s milk","B":"Brucella melitensis is the most common type of infection","C":"CFT is more important in acute infection than agglutination reaction","D":"May present as pyrexia of unknown origin"},"correctOption":"C","explanation":"The source marks this statement as false; agglutination testing has the greater role described for acute brucellosis."},{"id":"q_past_30","source":"Past Exam","topic":"Formative 2","text":"Which is not a recognised complication of acute shigellosis","options":{"A":"Haemolytic-uraemic syndrome","B":"Reiter''s syndrome","C":"Liver abscess","D":"Endotoxic shock"},"correctOption":"C","explanation":"Liver abscess is not a recognized typical complication of acute shigellosis in the source."},{"id":"q_past_31","source":"Past Exam","topic":"Formative 2","text":"Which is not a complication of Salmonella species","options":{"A":"Endocarditis","B":"Bronchiectasis","C":"Osteomyelitis","D":"Pyelonephritis"},"correctOption":"B","explanation":"The source identifies bronchiectasis as the non-complication among the listed Salmonella outcomes."},{"id":"q_past_32","source":"Past Exam","topic":"Formative 2","text":"Botulism is manifested by all except","options":{"A":"Normal pupils","B":"Entirely normal sensory functions","C":"Increased protein in CSF","D":"Progressive descending muscle paralysis"},"correctOption":"C","explanation":"Botulism is a neuromuscular paralytic illness; increased CSF protein is not a characteristic manifestation."},{"id":"q_past_33","source":"Past Exam","topic":"Formative 2","text":"Woolsorter''s disease is","options":{"A":"Plague","B":"Legionnaires'' disease","C":"Klebsiella-induced pneumonia","D":"Anthrax"},"correctOption":"D","explanation":"Woolsorter ’ s disease is the inhalational form of anthrax associated with contaminated animal products."},{"id":"q_past_34","source":"Past Exam","topic":"Formative 2","text":"Which is not a cause of aseptic fever","options":{"A":"Crush injury","B":"SLE","C":"AIDS","D":"Pontine haemorrhage"},"correctOption":"C","explanation":"The source marks AIDS as the exception in this aseptic-fever question."},{"id":"q_past_35","source":"Past Exam","topic":"Formative 2","text":"Which of the following is false in hydatid disease of liver","options":{"A":"Caused by larval stage of Echinococcus granulosus","B":"Diagnostic aspiration may produce anaphylaxis","C":"Casoni''s test is positive in all","D":"Albendazole therapy is most efficacious"},"correctOption":"C","explanation":"Casoni testing is not positive in every patient with hepatic hydatid disease, so the universal statement is false."},{"id":"q_past_36","source":"Past Exam","topic":"Formative 2","text":"Cysticercosis is the larval stage of","options":{"A":"Taenia solium","B":"Hymenolepis nana","C":"Taenia saginata","D":"Ancylostoma duodenale"},"correctOption":"A","explanation":"Cysticercosis is caused by the larval stage of Taenia solium."},{"id":"q_past_37","source":"Past Exam","topic":"Formative 2","text":"Which of the following does not produce hypothermia","options":{"A":"Neuroleptic malignant syndrome","B":"Panhypopituitarism","C":"Peripheral circulatory failure","D":"Myxoedema coma"},"correctOption":"A","explanation":"The source marks neuroleptic malignant syndrome as the condition that does not produce hypothermia."},{"id":"q_past_38","source":"Past Exam","topic":"Formative 2","text":"The main pathogenic organism in non-gonococcal urethritis is","options":{"A":"Ureaplasma urealyticum","B":"Chlamydia trachomatis","C":"Trichomoniasis","D":"Herpes simplex"},"correctOption":"B","explanation":"Chlamydia trachomatis is a major cause of nongonococcal urethritis."},{"id":"q_past_39","source":"Past Exam","topic":"Formative 2","text":"Which of the following is not seen in typhoid state","options":{"A":"Flapping tremor","B":"Coma vigil","C":"Subsultus tendinum","D":"Carphology"},"correctOption":"A","explanation":"Flapping tremor is not a typical feature of the typhoid state in the source."},{"id":"q_past_40","source":"Past Exam","topic":"Formative 2","text":"Which of the following is false regarding Widal test","options":{"A":"An agglutination reaction","B":"In vaccinated subjects, the O-titre disappears in time but H-agglutinins persist for years","C":"Titre of O antigen above 1:640 is often very significant in enteric fever","D":"Antibiotic therapy may depress the agglutination titres"},"correctOption":"B","explanation":"The source marks In vaccinated subjects, the O-titre disappears in time but H-agglutinins persist for years as the exception. The question is testing recognition of the statement that does not fit the expected features of the condition."},{"id":"q_past_41","source":"Past Exam","topic":"Formative 3","text":"The patient is considered comatose when Glasgow coma scale less than or equal to","options":{"A":"3","B":"10","C":"8","D":"5","E":"12"},"correctOption":"C","explanation":"A GCS of 8 or less is used as the threshold for coma in this question."},{"id":"q_past_42","source":"Past Exam","topic":"Formative 3","text":"The best score in Glasgow coma scale is","options":{"A":"10","B":"15","C":"20","D":"22","E":"18"},"correctOption":"B","explanation":"The maximum possible Glasgow Coma Scale score is 15."},{"id":"q_past_43","source":"Past Exam","topic":"Formative 3","text":"Which of the following causing bacterial meningitis?","options":{"A":"Cryptococcus neoformans","B":"Toxoplasmosis","C":"Malignant malaria","D":"Neisseria meningitidis","E":"Naegleria fowleri"},"correctOption":"D","explanation":"Neisseria meningitidis is a classic cause of acute bacterial meningitis and meningococcal outbreaks."},{"id":"q_past_44","source":"Past Exam","topic":"Formative 3","text":"Which of the following causing a septic meningitis?","options":{"A":"H. influenzae type B","B":"Neisseria meningitidis","C":"Streptococcus pneumoniae","D":"Staphylococcus aureus","E":"Cryptococcus neoformans"},"correctOption":"E","explanation":"Cryptococcus neoformans is an important cause of meningitis, especially in immunocompromised patients."},{"id":"q_past_45","source":"Past Exam","topic":"Formative 3","text":"Which of the following is correct about CSF examination in bacterial meningitis?","options":{"A":"Low tension <180 mm H ₂ O","B":"Turbid aspect","C":"High lymphocytes","D":"High protein 50 – 100 mg/dL","E":"Glucose >40 mg/dL"},"correctOption":"B","explanation":"Bacterial meningitis commonly produces turbid CSF because of the high cellular/protein burden."},{"id":"q_past_46","source":"Past Exam","topic":"Formative 3","text":"Which of the following is incorrect about CSF examination in viral meningitis?","options":{"A":"Low tension <180 mm H ₂ O","B":"Turbid aspect","C":"High lymphocytes","D":"High protein 50 – 100 mg/dL","E":"Glucose >40 mg/dL"},"correctOption":"B","explanation":"Bacterial meningitis commonly produces turbid CSF because of the high cellular/protein burden."},{"id":"q_past_47","source":"Past Exam","topic":"Formative 3","text":"Malaria can affect","options":{"A":"One million cases per year","B":"More than one million per year","C":"Less than one million"},"correctOption":"B","explanation":"The source gives this figure to emphasize the large global burden of malaria."},{"id":"q_past_48","source":"Past Exam","topic":"Formative 3","text":"The most dangerous type of malaria is","options":{"A":"Vivax","B":"P. malariae","C":"Falciparum","D":"Ovale"},"correctOption":"C","explanation":"Plasmodium falciparum is the malaria species associated with the most severe disease and major complications."},{"id":"q_past_49","source":"Past Exam","topic":"Formative 3","text":"The infective stage of malaria is","options":{"A":"Ring stage","B":"Trophozoite","C":"Sporozoites","D":"Merozoites"},"correctOption":"C","explanation":"Sporozoites are the infective stage of Plasmodium transmitted to humans by the female Anopheles mosquito."},{"id":"q_past_50","source":"Past Exam","topic":"Formative 3","text":"Cerebral malaria can be caused by","options":{"A":"P. vivax","B":"P. malariae","C":"P. ovale","D":"P. falciparum"},"correctOption":"D","explanation":"Plasmodium falciparum is the malaria species associated with the most severe disease and major complications."},{"id":"q_past_51","source":"Past Exam","topic":"Formative 3","text":"Sexual cycle of malaria occurs in","options":{"A":"Inside liver cells","B":"Inside RBCs","C":"In the WBCs","D":"Gut of mosquito"},"correctOption":"D","explanation":"The sexual cycle of Plasmodium occurs in the mosquito, including fertilization and development in its gut."},{"id":"q_past_52","source":"Past Exam","topic":"Formative 3","text":"Complicated malaria can develop in","options":{"A":"Children","B":"Pregnant female","C":"Both"},"correctOption":"C","explanation":"The source marks Both. This is the key association being tested by the question."},{"id":"q_past_53","source":"Past Exam","topic":"Formative 3","text":"Malaria can be transmitted by","options":{"A":"Sand fly","B":"Male Anopheles mosquito","C":"Female Anopheles mosquito"},"correctOption":"C","explanation":"Malaria is transmitted by the bite of the female Anopheles mosquito."},{"id":"q_past_54","source":"Past Exam","topic":"Formative 3","text":"Uncomplicated falciparum can be treated by","options":{"A":"Chloroquine","B":"Chloroquine + Primaquine","C":"ACTs therapy"},"correctOption":"C","explanation":"Plasmodium falciparum is the malaria species associated with the most severe disease and major complications."},{"id":"q_past_55","source":"Past Exam","topic":"Formative 3","text":"Sickle cell patients are","options":{"A":"More liable to malaria","B":"Less liable to malaria","C":"Has no role"},"correctOption":"B","explanation":"The source identifies relative protection against severe malaria in sickle-cell patients as the tested association."},{"id":"q_past_56","source":"Past Exam","topic":"Formative 3","text":"Which type of bite represents a potential medical emergency in an asplenic patient?","options":{"A":"Cat bite","B":"Dog bite","C":"Fish bite","D":"Human bite"},"correctOption":"B","explanation":"In an asplenic patient, dog bites can be a medical emergency because of severe risk from encapsulated/zoonotic organisms."},{"id":"q_past_57","source":"Past Exam","topic":"Formative 3","text":"Mefloquine is used for prophylaxis against malaria","options":{"A":"One day before travelling to endemic area","B":"2 days before travelling","C":"3 days before travelling","D":"One week before travelling"},"correctOption":"D","explanation":"The source marks one week before travel as the timing for mefloquine prophylaxis."},{"id":"q_past_58","source":"Past Exam","topic":"Formative 3","text":"Generalized lymphadenopathy is considered if there is","options":{"A":"Enlargement of more than two non-contiguous lymph node groups","B":"Enlargement of less than two non-contiguous lymph node groups","C":"Enlargement of more than two contiguous lymph node groups","D":"Enlargement of one lymph node group"},"correctOption":"A","explanation":"Generalized lymphadenopathy means involvement of more than two non-contiguous lymph-node groups."},{"id":"q_past_59","source":"Past Exam","topic":"Formative 3","text":"Male patient 50 years old, farmer, came to ER by hematemesis, splenic size was 25 cm, esophageal varices, etiology of splenomegaly in such case is","options":{"A":"Myelofibrosis","B":"Egyptian splenomegaly","C":"Hyperthyroidism","D":"Syphilis"},"correctOption":"B","explanation":"The source associates marked splenomegaly with portal-hypertension/Schistosoma- related Egyptian splenomegaly in this clinical scenario."},{"id":"q_past_60","source":"Past Exam","topic":"Formative 3","text":"Male patient 22 years old, presented by fever, generalized lymphadenopathy, diarrhea, weight loss, he has a history of IV drug addiction. What is most highly suspected in such case?","options":{"A":"TB infection","B":"Meningitis","C":"Acute myeloid leukemia","D":"AIDS"},"correctOption":"D","explanation":"The source marks AIDS as the exception in this aseptic-fever question."},{"id":"q_past_61","source":"Past Exam","topic":"Formative 4","text":"During premarital care, the following vaccine/s could be given","options":{"A":"Hepatitis B","B":"Tetanus toxoid","C":"Rubella","D":"All of the above","E":"A & B"},"correctOption":"D","explanation":"The source marks All of the above. This is the key association being tested by the question."},{"id":"q_past_62","source":"Past Exam","topic":"Formative 4","text":"One of the following vaccines is not given to symptomatic HIV children","options":{"A":"HAV","B":"HBV","C":"OPV","D":"DPT","E":"None of the above"},"correctOption":"C","explanation":"The source marks OPV as the exception. The question is testing recognition of the statement that does not fit the expected features of the condition."},{"id":"q_past_63","source":"Past Exam","topic":"Formative 4","text":"HIV is a","options":{"A":"DNA Pox virus","B":"RNA Ribovirus","C":"Single strand RNA Retrovirus","D":"40 nanometer diameter","E":"Double strand RNA virus"},"correctOption":"C","explanation":"HIV is an enveloped single-stranded RNA retrovirus."},{"id":"q_past_64","source":"Past Exam","topic":"Formative 4","text":"Tetanus toxoid is better given to the pregnant mother in","options":{"A":"In the first trimester","B":"One day before delivery","C":"From 4 to 8 months of pregnancy","D":"Just after delivery"},"correctOption":"C","explanation":"The source marks the 4 – 8 month interval as the preferred timing for tetanus toxoid during pregnancy."},{"id":"q_past_65","source":"Past Exam","topic":"Formative 4","text":"One of the following is not a method of HIV infection","options":{"A":"Feco-oral route","B":"I.V drug users and sharing needle","C":"Sexual relations","D":"Vertical transmission of infected mothers","E":"Lactation"},"correctOption":"A","explanation":"The source marks Feco-oral route as the exception. The question is testing recognition of the statement that does not fit the expected features of the condition."},{"id":"q_past_66","source":"Past Exam","topic":"Formative 4","text":"A newly married female has decided to receive (MMR) vaccine, the doctor advised her to postpone pregnancy for","options":{"A":"Only one month","B":"For at least 3 months","C":"For one year","D":"Not at all"},"correctOption":"B","explanation":"After an MMR vaccine, pregnancy is postponed for the interval specified in the source."},{"id":"q_past_67","source":"Past Exam","topic":"Formative 4","text":"Which one of the following is wrong about AIDS","options":{"A":"HIV equals AIDS","B":"CD4 count less than 200 cell/ml","C":"Presence of severe opportunistic infections","D":"Kaposi sarcoma could be seen","E":"Severely ill cachectic patient with fever"},"correctOption":"A","explanation":"HIV infection and AIDS are not synonymous; AIDS represents advanced HIV disease meeting defining criteria."},{"id":"q_past_68","source":"Past Exam","topic":"Formative 4","text":"Expanded program on immunization (EPI) include all of the following steps EXCEPT","options":{"A":"Immunization against the 7 target diseases with BCG, DPT, Sabin, HBV and Measles vaccines","B":"Maternal immunization with tetanus toxoid (T.T.)","C":"Immunization of all children against influenza virus","D":"Reduction of measles cases by 90% and mortalities by 95%"},"correctOption":"C","explanation":"The source marks Immunization of all children against influenza virus as the exception. The question is testing recognition of the statement that does not fit the expected features of the condition."},{"id":"q_past_69","source":"Past Exam","topic":"Formative 4","text":"Tetanus toxoid (T.T) first dose is best delayed to 20 weeks because if it is given earlier","options":{"A":"May cause congenital anomalies","B":"May cause abortion","C":"May cause intrauterine infection","D":"All of the above","E":"None of the above"},"correctOption":"D","explanation":"The source identifies All of the above as the causative organism or etiologic answer tested by this question."},{"id":"q_past_70","source":"Past Exam","topic":"Formative 4","text":"Target population of the program (EPI)","options":{"A":"Children from 0-1 years (Basic vaccines)","B":"Booster doses from one year to school entry","C":"Women in child bearing period (tetanus toxoid)","D":"All of the above"},"correctOption":"D","explanation":"The source marks All of the above. This is the key association being tested by the question."},{"id":"q_past_71","source":"Past Exam","topic":"Formative 4","text":"The general objectives of the program are the following except","options":{"A":"To reduce morbidity from the covered diseases","B":"To minimize effort and cost of treatment","C":"To promote a new healthy generation","D":"To promote geriatric generation"},"correctOption":"D","explanation":"The source marks To promote geriatric generation as the exception. The question is testing recognition of the statement that does not fit the expected features of the condition."},{"id":"q_past_72","source":"Past Exam","topic":"Formative 4","text":"The WHO established a standardized vaccination schedule for the original EPI which included the following vaccines except","options":{"A":"Bacillus Calmette-Gu é rin (BCG)","B":"Rota virus vaccine","C":"Diphtheria-tetanus-pertussis (DTP)","D":"Oral polio and Measles"},"correctOption":"B","explanation":"The original EPI vaccine package did not include rotavirus vaccine in the schedule described by the source."},{"id":"q_past_73","source":"Past Exam","topic":"Formative 4","text":"Absolute contraindications to vaccination","options":{"A":"Severe illness that needs hospitalization","B":"Recent receipt of blood","C":"HIV infection is an absolute contraindication to administration of live attenuated vaccines","D":"Pregnancy"},"correctOption":"C","explanation":"The source specifies symptomatic HIV infection as a contraindication to live attenuated vaccines."},{"id":"q_past_74","source":"Past Exam","topic":"Formative 4","text":"Toxoplasmosis is infection with Toxoplasma gondii. The only known hosts of this organism are domestic cats and their relatives. Infection with T. gondii in humans can occur in various ways. Which of the following is the most common mode of infection in humans?","options":{"A":"Blood transfusion","B":"Ingestion of oocysts","C":"Ingestion of tissue cysts","D":"Transplacental transmission"},"correctOption":"B","explanation":"Oocyst ingestion is a recognized route of Toxoplasma gondii acquisition in humans."},{"id":"q_past_75","source":"Past Exam","topic":"Formative 4","text":"Infection with T. gondii can manifest in many different ways. Which of the following types of toxoplasmosis results from congenital infection that is reactivated in a patient ’ s late teens or 20s?","options":{"A":"Acute","B":"Disseminated","C":"CNS","D":"Ocular"},"correctOption":"D","explanation":"Ocular toxoplasmosis can result from reactivation of congenital infection later in life."},{"id":"q_past_76","source":"Past Exam","topic":"Formative 4","text":"What things can you get from a restaurant that will cause you to gain this parasite?","options":{"A":"Rotten foods","B":"Uncooked meat","C":"Clean water","D":"Unwashed vegetables","E":"B & D f. A & D"},"correctOption":"E","explanation":"The source-marked combination is B & D for this toxoplasmosis exposure question."},{"id":"q_past_77","source":"Past Exam","topic":"Formative 4","text":"Toxoplasmosis is diagnosed using an indirect fluorescent antibody (IFA) test or enzyme immunoassay (EIA) for IgG or IgM antibodies. Which of the following results of serologic testing for T. gondii indicates that a patient has a possible acute infection?","options":{"A":"IgG is equivocal; IgM is positive","B":"IgG is positive; IgM is equivocal","C":"IgG is positive; IgM is negative"},"correctOption":"A","explanation":"A positive IgM with equivocal IgG can indicate a possible recent/acute Toxoplasma infection."},{"id":"q_past_78","source":"Past Exam","topic":"Formative 4","text":"If prenatal diagnosis reveals infection in the fetus, the pregnant patient should receive","options":{"A":"Sulfadiazine and pyrimethamine","B":"Folinic acid","C":"Spiramycin","D":"A & B"},"correctOption":"D","explanation":"The source marks A & B as the most likely diagnosis/answer for the clinical pattern described."},{"id":"q_past_79","source":"Past Exam","topic":"Formative 4","text":"The most affected WBC of the immune system with HIV infection is","options":{"A":"CD8 T-lymphocyte","B":"CD4 T-lymphocyte","C":"Plasma cell","D":"Macrophage","E":"CD3 T-lymphocyte"},"correctOption":"B","explanation":"HIV preferentially infects CD4 T lymphocytes, causing progressive depletion of this cell population."},{"id":"q_past_80","source":"Past Exam","topic":"Formative 4","text":"Laboratory methods of HIV diagnosis includes all except","options":{"A":"Rapid detection test","B":"ELISA 3rd generation","C":"ELISA 4th generation","D":"Quantiferon gold test","E":"HIV RNA PCR"},"correctOption":"D","explanation":"Quantiferon is a TB immunologic assay, not a standard laboratory method for diagnosing HIV infection."},{"id":"q_past_81","source":"Past Exam","topic":"Formative 5","text":"Risk factors for meningitis include all of the followings except","options":{"A":"HIV infection","B":"Military recruits","C":"Chronic liver disease","D":"College dorm residents"},"correctOption":"C","explanation":"The source marks Chronic liver disease as the exception. The question is testing recognition of the statement that does not fit the expected features of the condition."},{"id":"q_past_82","source":"Past Exam","topic":"Formative 5","text":"The following statements are true regarding leptospirosis, except","options":{"A":"It is zoonosis","B":"Man is the dead-end host","C":"Man is an accidental host","D":"Lice act as reservoirs of infection"},"correctOption":"D","explanation":"Leptospirosis is a zoonosis associated with animal reservoirs; lice are not its reservoir in the source."},{"id":"q_past_83","source":"Past Exam","topic":"Formative 5","text":"How is leptospirosis transmitted?","options":{"A":"Exposure of mucous membranes or abraded skin to the contaminated water","B":"By mosquito bites","C":"By contact with the infected person"},"correctOption":"A","explanation":"The source marks Exposure of mucous membranes or abraded skin to the contaminated water. This is the key association being tested by the question."},{"id":"q_past_84","source":"Past Exam","topic":"Formative 5","text":"Besides the classic triad, what ’ s another sign or symptom that you may find in a patient with bacterial meningitis?","options":{"A":"Urinary frequency","B":"Abdominal pain","C":"Constipation","D":"Confusion"},"correctOption":"D","explanation":"Confusion is a recognized additional neurologic manifestation of bacterial meningitis and indicates CNS dysfunction."},{"id":"q_past_85","source":"Past Exam","topic":"Formative 5","text":"Which form of leptospirosis is known as Weil ’ s disease?","options":{"A":"Icteric","B":"Anicteric","C":"Both"},"correctOption":"A","explanation":"Weil disease is the severe icteric form of leptospirosis."},{"id":"q_past_86","source":"Past Exam","topic":"Formative 5","text":"Generalized lymphadenopathy is considered if there is:","options":{"A":"Enlargement of more than two non-contiguous lymph node groups","B":"Enlargement of less than two non-contiguous lymph node groups","C":"Enlargement of more than two contiguous lymph node groups","D":"Enlargement of one lymph node group"},"correctOption":"A","explanation":"Generalized lymphadenopathy means involvement of more than two non-contiguous lymph-node groups."},{"id":"q_past_87","source":"Past Exam","topic":"Formative 5","text":"Male patient 50 years old, farmer, came to ER by hematemesis, splenic size was 25 cm, esophageal varices, etiology of splenomegaly in such case?","options":{"A":"Myelofibrosis","B":"Egyptian splenomegaly","C":"Hyperthyroidism","D":"Syphilis"},"correctOption":"B","explanation":"The source associates marked splenomegaly with portal-hypertension/Schistosoma- related Egyptian splenomegaly in this clinical scenario."},{"id":"q_past_88","source":"Past Exam","topic":"Formative 5","text":"Which of the following parasites is not a cause for aseptic meningitis?","options":{"A":"Naegleria","B":"Entamoeba histolytica","C":"Strongyloides stercoralis","D":"Taenia solium"},"correctOption":"B","explanation":"The source marks Entamoeba histolytica as the exception. The question is testing recognition of the statement that does not fit the expected features of the condition."},{"id":"q_past_89","source":"Past Exam","topic":"Formative 5","text":"Male patient 29 years old, butcher, presented to OPC by fever, days of fever followed by days without fever, associated with profuse sweating and back pain. His CBC showed mild anemia and leukocytosis. What is the most probable diagnosis?","options":{"A":"Typhoid fever","B":"Malaria","C":"Non-Hodgkin lymphoma","D":"Brucellosis"},"correctOption":"D","explanation":"The source marks Brucellosis as the most likely diagnosis/answer for the clinical pattern described."},{"id":"q_past_90","source":"Past Exam","topic":"Formative 5","text":"Which one of the following causes hypothalamic reset?","options":{"A":"Prostaglandin F","B":"T-regulator cells","C":"Prostaglandin E2","D":"Cell adhesion molecule"},"correctOption":"C","explanation":"The source identifies Prostaglandin E2 as the causative organism or etiologic answer tested by this question."},{"id":"q_past_91","source":"Past Exam","topic":"Formative 5","text":"In neutropenic fever, absolute count of neutrophils is?","options":{"A":"≤ 1000 per mm ³","B":"≤ 500 per mm ³","C":"≤ 850 per mm ³","D":">1000 per mm ³"},"correctOption":"B","explanation":"The source marks ≤ 500 per mm ³ . This is the key association being tested by the question."},{"id":"q_past_92","source":"Past Exam","topic":"Formative 5","text":"Inflammation of the brain parenchyma is referred to as","options":{"A":"Meningitis","B":"Myelitis","C":"Encephalitis","D":"Meningoencephalitis"},"correctOption":"C","explanation":"The source marks Encephalitis. This is the key association being tested by the question."},{"id":"q_past_93","source":"Past Exam","topic":"Formative 5","text":"Male patient 22 years old, presented by fever, generalized lymphadenopathy, diarrhea, weight loss, he has a history of IV drug addiction. What most highly suspected in such case?","options":{"A":"TB infection","B":"Meningitis","C":"Acute myeloid leukemia","D":"AIDS"},"correctOption":"D","explanation":"The source marks AIDS as the exception in this aseptic-fever question."},{"id":"q_past_94","source":"Past Exam","topic":"Formative 5","text":"Meningitis reflects infection of the","options":{"A":"Arachnoid mater and pia mater","B":"Arachnoid mater and subarachnoid space","C":"Dura mater and arachnoid mater","D":"Subarachnoid space and pia mater"},"correctOption":"B","explanation":"The source marks Arachnoid mater and subarachnoid space. This is the key association being tested by the question."},{"id":"q_past_95","source":"Past Exam","topic":"Formative 5","text":"Which of the following bacteria is not a cause for bacterial meningitis?","options":{"A":"Streptococcus pneumoniae","B":"Neisseria meningitidis","C":"Escherichia coli","D":"Haemophilus influenzae"},"correctOption":"C","explanation":"The source marks Escherichia coli as the exception. The question is testing recognition of the statement that does not fit the expected features of the condition."},{"id":"q_past_96","source":"Past Exam","topic":"Formative 5","text":"Which of the following organisms causes epidemic meningitis cases at military recruits?","options":{"A":"Haemophilus influenzae type b","B":"Neisseria meningitidis","C":"Streptococcus pneumoniae","D":"Listeria monocytogenes"},"correctOption":"B","explanation":"Neisseria meningitidis is a classic cause of acute bacterial meningitis and meningococcal outbreaks."},{"id":"q_past_97","source":"Past Exam","topic":"Formative 5","text":"Which are the two types of leptospirosis?","options":{"A":"Icteric and Anicteric","B":"Edematous and Non-edematous","C":"Haemorrhagic and Non-haemorrhagic","D":"Benign and malignant"},"correctOption":"A","explanation":"Weil disease is the severe icteric form of leptospirosis."},{"id":"q_past_98","source":"Past Exam","topic":"Formative 5","text":"Aseptic meningitis diagnosed when","options":{"A":"No organisms demonstrated by gram stain or bacterial cultures","B":"No organisms demonstrated by gram stain but detected by bacterial cultur